package com.ruoyi.web.controller.shop;
import java.util.List; import javax.servlet.http.HttpServletResponse; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.annotation.Log; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.common.core.page.TableDataInfo; import com.ruoyi.common.enums.BusinessType; import com.ruoyi.common.utils.poi.ExcelUtil; import com.ruoyi.system.domain.shop.MallMember; import com.ruoyi.system.service.IMallMemberService;
@RestController @RequestMapping("/shop/member") public class MallMemberController extends BaseController { @Autowired private IMallMemberService memberService; @PreAuthorize("@ss.hasPermi('shop:member:list')") @GetMapping("/list") public TableDataInfo list(MallMember member){startPage();List<MallMember> list=memberService.selectMemberList(member);return getDataTable(list);} @Log(title="商城会员",businessType=BusinessType.EXPORT) @PreAuthorize("@ss.hasPermi('shop:member:export')") @PostMapping("/export") public void export(HttpServletResponse response,MallMember member){List<MallMember> list=memberService.selectMemberList(member);new ExcelUtil<MallMember>(MallMember.class).exportExcel(response,list,"商城会员数据");} @PreAuthorize("@ss.hasPermi('shop:member:query')") @GetMapping("/{memberId}") public AjaxResult getInfo(@PathVariable Long memberId){return success(memberService.selectMemberById(memberId));} @PreAuthorize("@ss.hasPermi('shop:member:sensitive')") @GetMapping("/{memberId}/addresses") public AjaxResult addresses(@PathVariable Long memberId){return success(memberService.selectAddresses(memberId));} @PreAuthorize("@ss.hasPermi('shop:member:status')") @Log(title="商城会员",businessType=BusinessType.UPDATE) @PutMapping("/{memberId}/status") public AjaxResult status(@PathVariable Long memberId,@RequestBody MallMember member){return toAjax(memberService.updateStatus(memberId,member.getStatus()));} }
